package dev.zomboid.hordes;
import java.util.*;import java.lang.ref.WeakReference;import java.io.*;import java.nio.file.*;
import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.bus.api.EventPriority;
@EventBusSubscriber(modid="zomboid_hordes")
public final class ItemCleanup {
 public static final String[] KEYS={"limpieza_activa_todos","limpieza_min_minutos","limpieza_max_minutos","limpieza_edad_minutos","limpieza_aviso_todos","limpieza_aviso_segundos","limpiar_objetos_todos"};
 public static final String DEFAULT_MESSAGE="Limpieza de objetos tirados en {segundos} segundos. Recoge lo que quieras conservar.";
 private static WeakReference<Object> currentWorld=new WeakReference<>(null);
 public static void prepareWorld(Object server){if(currentWorld.get()!=server){currentWorld=new WeakReference<>(server);message=DEFAULT_MESSAGE;}}
 private static String message=DEFAULT_MESSAGE,staged;private static final Map<Object,State> STATES=new WeakHashMap<>();
 private static final class State {final Map<UUID,WeakReference<Object>> items=new HashMap<>();ArrayDeque<UUID> queue;long next=-1,deadline;String signature="";boolean loaded,notice,automatic;int deleted;}
 private static Object c(Object o,String n,Object...a){return ZoneReflection.call(o,n,a);}private static boolean yes(Object o){return Boolean.TRUE.equals(o);}
 private static State state(Object server){return STATES.computeIfAbsent(server,k->new State());}
 public static void install(Map<String,Double>d,Map<String,Double>lo,Map<String,Double>hi,Map<String,Double>v){double[] defaults={0,10,20,1,0,30,0},mins={0,1,1,0,0,1,0},maxs={1,1440,1440,1440,1,300,1};for(int i=0;i<KEYS.length;i++){d.put(KEYS[i],defaults[i]);lo.put(KEYS[i],mins[i]);hi.put(KEYS[i],maxs[i]);v.putIfAbsent(KEYS[i],defaults[i]);}}
 public static void validate(Map<String,Double> v){if(v.get(KEYS[1])>v.get(KEYS[2]))throw new IllegalArgumentException("La limpieza mínima no puede superar la máxima.");}
 public static String checkedMessage(String s){if(s==null||s.length()>160||s.chars().anyMatch(ch->ch<32||ch==127))throw new IllegalArgumentException("El aviso debe tener hasta 160 caracteres y una sola línea.");return s.isBlank()?DEFAULT_MESSAGE:s;}
 public static void stage(String s){staged=checkedMessage(s);}public static void unstage(){staged=null;}public static String message(){return message;}
 public static void store(Properties p,OutputStream out,String comment)throws IOException {p.setProperty("limpieza_mensaje",staged==null?message:staged);p.store(out,comment);}
 private static long delay(double min,double max,double roll){return (long)((min+(max-min)*Math.clamp(roll,0,1))*60_000_000_000L);}
 public static long interval(double min,double max,double roll){if(!Double.isFinite(min)||!Double.isFinite(max)||min<1||max<min||max>1440)throw new IllegalArgumentException("Intervalo inválido");return delay(min,max,roll);}
 public static boolean oldEnough(int age,double minutes){return age>=minutes*1200;}
 private static void schedule(State s,long now){s.next=now+interval(WorldTuning.get(KEYS[1]),WorldTuning.get(KEYS[2]),Math.random());}
 public static void applied(Map<String,Double> values,Object server){boolean manual=values.getOrDefault(KEYS[6],0d)>0;values.put(KEYS[6],0d);if(server==null)return;State s=state(server);if(!s.loaded){message=DEFAULT_MESSAGE;try{Object root=ZoneReflection.get(ZoneReflection.type("net.minecraft.world.level.storage.LevelResource"),"ROOT");Path file=((Path)c(server,"getWorldPath",root)).resolve("serverconfig/zomboid-hordes-controls.properties");if(Files.exists(file)){Properties p=new Properties();try(InputStream in=Files.newInputStream(file)){p.load(in);}message=checkedMessage(p.getProperty("limpieza_mensaje",DEFAULT_MESSAGE));}}catch(IOException|RuntimeException e){System.getLogger("ItemCleanup").log(System.Logger.Level.WARNING,"No se pudo leer el aviso de limpieza",e);}s.loaded=true;}if(staged!=null)message=staged;
  String sig=values.get(KEYS[0])+":"+values.get(KEYS[1])+":"+values.get(KEYS[2]);long now=System.nanoTime();if(!sig.equals(s.signature)){s.signature=sig;s.queue=null;s.deadline=0;s.next=-1;if(values.get(KEYS[0])>0)schedule(s,now);}if(manual)start(server,s,now,false);
 }
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void join(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e){if(e.getLevel().isClientSide||e.isCanceled()||!ZoneReflection.type("net.minecraft.world.entity.item.ItemEntity").isInstance(e.getEntity()))return;Object server=c(e.getLevel(),"getServer");if(server!=null)state(server).items.put((UUID)c(e.getEntity(),"getUUID"),new WeakReference<>(e.getEntity()));}
 @SubscribeEvent public static void leave(net.neoforged.neoforge.event.entity.EntityLeaveLevelEvent e){var entity=e.getEntity();if(entity.level().isClientSide||!ZoneReflection.type("net.minecraft.world.entity.item.ItemEntity").isInstance(entity))return;Object server=c(entity.level(),"getServer");State s=STATES.get(server);if(s!=null)s.items.remove((UUID)c(entity,"getUUID"));}
 private static void announce(Object server,String text){Object component=c(ZoneReflection.type("net.minecraft.network.chat.Component"),"literal",text);c(c(server,"getPlayerList"),"broadcastSystemMessage",component,false);}
 private static void start(Object server,State s,long now,boolean automatic){if(s.queue!=null||s.deadline!=0)return;s.automatic=automatic;s.notice=WorldTuning.flag(KEYS[4]);s.deleted=0;int sec=(int)WorldTuning.get(KEYS[5]);s.deadline=now+(s.notice?sec*1_000_000_000L:1);if(s.notice)announce(server,message.replace("{segundos}",Integer.toString(sec)));}
 public static void advance(Object server,long now){State s=state(server);if(!WorldTuning.flag(KEYS[0])){s.next=-1;if(s.automatic){s.deadline=0;s.queue=null;s.automatic=false;}}if(s.next>=0&&now>=s.next&&s.deadline==0&&s.queue==null)start(server,s,now,true);if(s.deadline!=0&&now>=s.deadline){s.deadline=0;s.queue=new ArrayDeque<>(s.items.keySet());}if(s.queue==null)return;long until=System.nanoTime()+2_000_000;int inspected=0;while(!s.queue.isEmpty()&&inspected++<32&&System.nanoTime()<until){UUID id=s.queue.removeFirst();WeakReference<Object> ref=s.items.get(id);Object item=ref==null?null:ref.get();if(item==null||yes(c(item,"isRemoved"))){s.items.remove(id);continue;}if(oldEnough(((Number)c(item,"getAge")).intValue(),WorldTuning.get(KEYS[3]))){c(item,"discard");s.items.remove(id);s.deleted++;}}if(s.queue.isEmpty()){s.queue=null;if(s.notice)announce(server,"Limpieza completada: "+s.deleted+" objetos tirados eliminados.");s.next=-1;if(WorldTuning.flag(KEYS[0]))schedule(s,now);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post e){if(e.getLevel().isClientSide)return;Object server=c(e.getLevel(),"getServer");if(server==null||e.getLevel()!=c(server,"overworld"))return;try{advance(server,System.nanoTime());}catch(RuntimeException ex){State s=state(server);s.queue=null;s.deadline=0;s.next=-1;System.getLogger("ItemCleanup").log(System.Logger.Level.ERROR,"Limpieza detenida por error",ex);}}
 @SubscribeEvent public static void stop(net.neoforged.neoforge.event.server.ServerStoppedEvent e){STATES.remove(e.getServer());message=DEFAULT_MESSAGE;staged=null;}
}
